css:
.print-format {
    background-color: white;
    border-radius: 0;
    max-width: 210mm;
    max-height: 297mm;
    padding: 0;
    margin: 5px;
    font-family: cairo;
  }

  .print-format td, .print-format th {
  padding: 5px !important;
}

@page {
    size: A4 portrait !important;
    margin: 0;
}


html, body {
    margin: 0;
    padding: 0;
    width: 210mm;
    max-height: 297mm;
    background-color: #fff;
}
.info_all{
    display: flex;
    justify-content: space-between;
    margin: 2px;
    padding: 1px;
}
.info_na{
    padding-top:20px;
   font-size:3rem;
   font-weight:700;
   color:#0b3d91;

}
.info_de{
    display:grid;
    padding-top:30px;
     font-size:.8rem;
   font-weight:600;
}
.image{
    width:200px;
    padding-left: 40px;
    padding-right:40px;
    padding-top:20px;
}
.info_con{
    display:flex;
    flex-wrap: wrap;
     margin: 2px;
    padding: 1px;
}
.boxed{
    flex:30%;
    border:1px solid #333;
    border-radius:12px;
    padding:.5rem 1rem .75rem;
    margin:5px;
  }
  .boxed > legend{
   text-align:center;
    font-weight:700;
    font-size:1rem;
  }
  .boxed_re{
    flex:30%;
    border:1px solid #333;
    border-radius:12px;
    padding:.5rem 1rem .75rem;
    margin:20px 2px 20px 2px;
    font-size: 1rem;
    font-weight:700;
  }
  .boxed_re > legend{
   text-align:center;
    font-weight:700;
    font-size:1.5rem;
  }
   :root{
    --header-bg:#eef5ff;   
    --header-fg:#0b3d91;   
    --row-alt:#f9fbff;    
    --border:#d0d7de;    
  }

  .tab{
    width:100%;
    border-collapse:collapse;
    direction:rtl;              
    font-size:13px;
    line-height:1.6;
    margin-top:20px;
  }
  .tab th, .tab td{
    border:1px solid var(--border);
    padding:8px 10px;
    vertical-align:middle;
  }
  .tab thead th{
    background:var(--header-bg);
    color:var(--header-fg);
    text-align:center;
    font-weight:700;
    letter-spacing:.2px;
    -webkit-print-color-adjust:exact; 
            print-color-adjust:exact;
  }
  .tab tbody tr:nth-of-type(odd){
    background:var(--row-alt);   
  }
  .tab tbody tr:hover{
    background:#eaf3ff;           
  }
  .tab td.num, .tab th.num{
    text-align:center;
    font-variant-numeric:tabular-nums;
    white-space:nowrap;
    width:48px;                 
  }
  .tab td.center{ text-align:center; }
  .tab td.end{ text-align:end; } 
  .tab th, .tab td{
  text-align: center;
}


  @media print{
    .tab tbody tr:hover{ background:transparent; }
  }

